<div class="notification-menu-wrap"><button type="button" class="notification-link" id="notification-trigger" aria-haspopup="true" aria-expanded="false" title="Notifications" aria-label="Notifications"><svg class="bell-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M18 9a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg><?php if($unread>0):?><span class="notification-count" id="notification-count"><?=e($unread)?></span><?php endif;?></button><div class="notification-dropdown" id="notification-dropdown" hidden><div class="notification-dropdown-head"><div><strong>Notifications</strong><?php if($unread>0):?><span class="notification-dropdown-unread" id="notification-unread-label"><?=e($unread)?> unread</span><?php endif;?></div><?php if($unread>0):?><button type="button" class="notification-mark-all" id="notification-mark-all">Mark all as read</button><?php endif;?></div><div class="notification-dropdown-list" id="notification-dropdown-list"><div class="notification-dropdown-loading">Loading notifications...</div></div></div></div><div class="profile-menu-wrap"><button type="button" class="user user-link profile-menu-trigger avatar-only-trigger" id="profile-menu-trigger" aria-haspopup="true" aria-expanded="false" title="Open profile menu" aria-label="Open profile menu"><?php if(!empty($_SESSION['user']['avatar_path'])): ?><img class="avatar" src="<?=e($_SESSION['user']['avatar_path'])?>" alt="Profile picture"><?php else: ?><span class="avatar"><?=e(strtoupper(substr($_SESSION['user']['name'],0,1)))?></span><?php endif; ?></button><div class="profile-menu" id="profile-menu" hidden><?php if(($_SESSION['user']['role']??'')==='student'): ?><a href="academic_progress.php">Academic Progress</a><a href="announcements.php">Announcements</a><a href="attendance.php">Attendance</a><a href="dashboard.php">Dashboard</a><a href="documents.php">Documents</a><a href="enrollment.php">Enrollment</a><a href="grades.php">Grades</a><a href="important_dates.php">Important Dates</a><a href="messaging.php">Messages</a><a href="schedule.php">My Schedules</a><a href="student_teams.php">My Teams</a><a href="tickets.php">My Ticket</a><div class="profile-menu-divider"></div><?php elseif(($_SESSION['user']['role']??'')==='faculty'): ?><a href="faculty_announcements.php">Announcements</a><a href="faculty_attendance.php">Attendance</a><a href="faculty_teams.php">Class Teams</a><a href="faculty.php">Dashboard</a><a href="faculty_enrollment.php">Enrollment Requests</a><a href="faculty_gradebook.php">Gradebook</a><a href="admin_important_dates.php">Important Dates</a><a href="messaging.php">Messages</a><a href="faculty_classes.php">My Classes</a><a href="faculty_students.php">Students</a><a href="faculty_schedule.php">Teaching Schedule</a><div class="profile-menu-divider"></div><?php elseif(($_SESSION['user']['role']??'')==='admin'): ?><a href="admin_inbox.php">Administration Inbox</a><a href="admin_announcements.php">Announcements</a><a href="admin_audit.php">Audit Log</a><a href="admin.php">Dashboard</a><a href="admin_enrollment.php">Enrollment</a><a href="admin_faculty.php">Faculty</a><a href="admin_gradebook.php">Gradebook</a><a href="admin_important_dates.php">Important Dates</a><a href="messaging.php">Messages</a><a href="admin_schedules.php">Schedules</a><a href="admin_students.php">Students</a><a href="admin_subjects.php">Subjects</a><a href="admin_tickets.php">Tickets</a><div class="profile-menu-divider"></div><?php endif; ?><a href="profile.php">My Profile</a><a class="profile-menu-signout" href="logout.php">Sign out</a></div></div></div></header><script>(function(){const pb=document.getElementById('profile-menu-trigger'),pm=document.getElementById('profile-menu');const nb=document.getElementById('notification-trigger'),nm=document.getElementById('notification-dropdown'),list=document.getElementById('notification-dropdown-list'),count=document.getElementById('notification-count'),label=document.getElementById('notification-unread-label'),markAll=document.getElementById('notification-mark-all');if(!pb||!pm||!nb||!nm)return;let loaded=false;function closeProfile(){pm.hidden=true;pb.setAttribute('aria-expanded','false');}function closeNotifications(){nm.hidden=true;nb.setAttribute('aria-expanded','false');}function esc(t){const d=document.createElement('div');d.textContent=t??'';return d.innerHTML;}function render(rows){if(!rows.length){list.innerHTML='<div class="notification-dropdown-empty">You have no notifications yet.</div>';return;}list.innerHTML=rows.map(n=>{const unread=Number(n.is_read)===0;const when=new Date(String(n.created_at).replace(' ','T')).toLocaleString([], {month:'short',day:'numeric',year:'numeric',hour:'numeric',minute:'2-digit'});return '<div class="notification-dropdown-item '+(unread?'unread':'read')+'" data-id="'+esc(n.id)+'"><div class="notification-dropdown-icon">'+esc((n.type||'G').charAt(0).toUpperCase())+'</div><div class="notification-dropdown-content"><div class="notification-dropdown-title">'+esc(n.title)+'</div><div class="notification-dropdown-message">'+esc(n.message)+'</div><div class="notification-dropdown-time">'+esc(when)+'</div>'+(unread?'<button type="button" class="notification-read-one" data-id="'+esc(n.id)+'">Mark as read</button>':'')+'</div></div>';}).join('');list.querySelectorAll('.notification-read-one').forEach(btn=>btn.addEventListener('click',function(e){e.stopPropagation();markOne(btn.dataset.id);}));}async function loadNotifications(){if(loaded)return;try{const r=await fetch('notifications.php?ajax=1',{headers:{'X-Requested-With':'XMLHttpRequest'}});const data=await r.json();render(data.notifications||[]);loaded=true;}catch(e){list.innerHTML='<div class="notification-dropdown-empty">Unable to load notifications.</div>';}}async function markOne(id){const fd=new FormData();fd.append('mark_read',id);fd.append('ajax','1');try{await fetch('notifications.php',{method:'POST',body:fd,headers:{'X-Requested-With':'XMLHttpRequest'}});loaded=false;await loadNotifications();updateCount();}catch(e){}}async function markAllRead(){if(!markAll)return;const fd=new FormData();fd.append('mark_read','all');fd.append('ajax','1');markAll.disabled=true;try{await fetch('notifications.php',{method:'POST',body:fd,headers:{'X-Requested-With':'XMLHttpRequest'}});loaded=false;await loadNotifications();updateCount();}catch(e){}finally{markAll.disabled=false;}}async function updateCount(){try{const r=await fetch('notifications.php?ajax=count',{headers:{'X-Requested-With':'XMLHttpRequest'}});const data=await r.json();const n=Number(data.unread||0);if(count){count.textContent=n;count.hidden=n===0;}else if(n>0){const s=document.createElement('span');s.id='notification-count';s.className='notification-count';s.textContent=n;nb.appendChild(s);}if(label){label.textContent=n+' unread';label.hidden=n===0;}if(markAll)markAll.hidden=n===0;}catch(e){}}nb.addEventListener('click',function(e){e.stopPropagation();closeProfile();nm.hidden=!nm.hidden;nb.setAttribute('aria-expanded',nm.hidden?'false':'true');if(!nm.hidden)loadNotifications();});if(markAll)markAll.addEventListener('click',markAllRead);pb.addEventListener('click',function(e){e.stopPropagation();closeNotifications();pm.hidden=!pm.hidden;pb.setAttribute('aria-expanded',pm.hidden?'false':'true');});document.addEventListener('click',function(e){if(!pm.contains(e.target)&&e.target!==pb)closeProfile();if(!nm.contains(e.target)&&e.target!==nb)closeNotifications();});document.addEventListener('keydown',function(e){if(e.key==='Escape'){closeProfile();closeNotifications();}});})();</script>
